const ABERTURA = {
  "pt-BR": "Bom dia! Estas são as principais notícias de hoje.",
  "en-US": "Good morning! Here are today's top stories.",
  "es-ES": "¡Buenos días! Estas son las principales noticias de hoy."
};
const FECHO = {
  "pt-BR": "Essas foram as notícias. Tenha um ótimo dia!",
  "en-US": "That's the news for today. Have a great day!",
  "es-ES": "Esas fueron las noticias. ¡Que tengas un gran día!"
};

function recente(item, limite) {
  if (!item.published) return true;
  try {
    return !dates.isBefore(item.published, limite);
  } catch (e) {
    return true;
  }
}

async function run() {
  const limite = dates.addHours(now(), -24);
  const quantidade = Math.min(20, Math.max(1, Math.round(params.quantidade)));
  const items = (await rss.read({url: params.feed, max: 30}))
    .filter(function (i) { return i.title && recente(i, limite); })
    .slice(0, quantidade);

  if (items.length === 0) {
    log("Nenhuma notícia das últimas 24 horas no feed.");
    return;
  }

  const partes = [ABERTURA[params.idioma] || ABERTURA["pt-BR"]];
  for (const item of items) {
    const r = await write.resumo({idioma: params.idioma, titulo: item.title, texto: item.summary || ""});
    const t = (r.text || "").trim();
    partes.push(t || item.title);
  }
  partes.push(FECHO[params.idioma] || FECHO["pt-BR"]);

  await audio.send({
    title: "📻 Notícias de " + dates.format(now(), "d 'de' MMMM"),
    text: partes.join("\n\n"),
    language: params.idioma
  });
}
